836  otError NcpBase::HandleCommand(uint8_t aHeader)
   837  {
   838      otError      error = OT_ERROR_NONE;
   839      unsigned int command;
   840
   841      SuccessOrExit(error = mDecoder.ReadUintPacked(command));
   842
   843      switch (command)
   844      {
   845      case SPINEL_CMD_NOOP:
   846          error = CommandHandler_NOOP(aHeader);
   847          break;
   848
   849      case SPINEL_CMD_RESET:
   850          error = CommandHandler_RESET(aHeader);
   851          break;
   852
   853      case SPINEL_CMD_PROP_VALUE_GET:
   854      case SPINEL_CMD_PROP_VALUE_SET:
   855      case SPINEL_CMD_PROP_VALUE_INSERT:
   856      case SPINEL_CMD_PROP_VALUE_REMOVE:
   857          error = CommandHandler_PROP_VALUE_update(aHeader, command);
   858          break;
   859
   860  #if OPENTHREAD_CONFIG_NCP_ENABLE_PEEK_POKE
   861      case SPINEL_CMD_PEEK:
   862          error = CommandHandler_PEEK(aHeader);
   863          break;
   864
   865      case SPINEL_CMD_POKE:
   866          error = CommandHandler_POKE(aHeader);
   867          break;
   868  #endif
   869
   870  #if OPENTHREAD_MTD || OPENTHREAD_FTD
   871      case SPINEL_CMD_NET_SAVE:
   872          error = CommandHandler_NET_SAVE(aHeader);
   873          break;
   874
   875      case SPINEL_CMD_NET_CLEAR:
   876          error = CommandHandler_NET_CLEAR(aHeader);
   877          break;
   878
   879      case SPINEL_CMD_NET_RECALL:
   880          error = CommandHandler_NET_RECALL(aHeader);
   881          break;
   882  #endif // OPENTHREAD_MTD || OPENTHREAD_FTD
   883
   884      default:
   885
   886  #if OPENTHREAD_ENABLE_NCP_VENDOR_HOOK
   887          if (command >= SPINEL_CMD_VENDOR__BEGIN && command < SPINEL_CMD_VENDOR__END)
   888          {
   889              error = VendorCommandHandler(aHeader, command);
   890              break;
   891          }
   892  #endif
   893
   894          error = PrepareLastStatusResponse(aHeader, SPINEL_STATUS_INVALID_COMMAND);
   895          break;
   896      }
   897
   898  exit:
   899      return error;
   900  }
